Action.Str:
function arr(v) {
    if (typeof v === "undefined" || v === null) return [];
    if (Array.isArray(v)) return v;
    return [v];
}
function clean(v) {
    return String(v == null ? "" : v).trim();
}
var texts = (typeof aitext !== "undefined") ? arr(aitext) : [];
var ids = (typeof aiid !== "undefined") ? arr(aiid) : [];
var coords = [];
if (typeof aicoordinates !== "undefined") coords = arr(aicoordinates);
else if (typeof aicoords !== "undefined") coords = arr(aicoords);
var count = Math.max(texts.length, ids.length, coords.length);
var nodes = [];
for (var i = 0; i < count && i < 240; i++) {
    var coord = String(coords[i] || "");
    var match = coord.match(/(-?\d+)\s*,\s*(-?\d+)/);
    var x = match ? parseInt(match[1], 10) : 0;
    var y = match ? parseInt(match[2], 10) : 0;
    nodes.push({
        index: i,
        depth: 0,
        text: clean(texts[i]),
        content_description: "",
        hint_text: "",
        class_name: "",
        view_id: clean(ids[i]),
        clickable: false,
        editable: false,
        scrollable: false,
        password: false,
        checkable: false,
        checked: false,
        focused: false,
        bounds: {left:x, top:y, right:x, bottom:y}
    });
}
var seen = {};
var summaryParts = [];
for (var j = 0; j < texts.length && summaryParts.length < 400; j++) {
    var value = clean(texts[j]);
    if (!value || seen[value]) continue;
    seen[value] = true;
    summaryParts.push(value);
}
var pkg = (typeof aipackage !== "undefined") ? clean(aipackage) : "";
var observation = {
    created_at_ms: Date.now(),
    package_name: pkg,
    text_summary: summaryParts.join("\n").slice(0, 25000),
    nodes: nodes
};
var envelope = {
    contract_version: 1,
    request_id: String(request_id || ""),
    callback_token: String(callback_token || ""),
    success: true,
    payload: JSON.stringify(observation),
    error: null
};
sendIntent(
    "com.fersaiyan.cyanbridge.TASKER_AGENT_RESPONSE",
    "receiver",
    "com.fersaiyan.cyanbridge",
    undefined, undefined, undefined, undefined,
    ["response:" + JSON.stringify(envelope)]
);
